const items = $input.all();
const contacts = items[0].json.results || [];
const byBusiness = { paragon_tax: 0, hh_insurance: 0, hh_consulting: 0, other: 0 };
const stalled = [];
for (const c of contacts) {
  const props = c.properties;
  if (props.paragon_referral_state) byBusiness.paragon_tax++;
  else if (props.hh_insurance_qualification_state) byBusiness.hh_insurance++;
  else if (props.hh_consulting_investor_state) byBusiness.hh_consulting++;
  else byBusiness.other++;
}
const summary = {
  date: $now.toFormat('yyyy-MM-dd'),
  contacts_touched_24h: contacts.length,
  by_business: byBusiness,
  stalled_count: stalled.length,
  bookings_next_48h_count: 0
};
return [{ json: summary }];
